import{_ as r,C as t,o,c as s,a2 as e,E as n}from"./chunks/framework.CDpkVv68.js";const b=JSON.parse('{"title":"Herrería","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/professions/blacksmithing.md","filePath":"es/guide/professions/blacksmithing.md"}'),l={name:"es/guide/professions/blacksmithing.md"};function d(c,a,p,m,h,u){const i=t("WikiVisual");return o(),s("div",null,[a[0]||(a[0]=e('<h1 id="blacksmithing" tabindex="-1">Herrería <a class="header-anchor" href="#blacksmithing" aria-label="Enlace permanente a &quot;Herrería&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · No establecido como jugable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Convierte el conocimiento del metal y el trabajo artesanal en equipo fiable.</li><li>Evalúa, mantén y repara equipo durante las expediciones.</li><li>La calidad exige compromisos; las <a href="/Syrolands-Public/es/guide/items/item-quality.html">obras maestras</a> deben seguir siendo raras.</li></ul><p><span id="at-a-glance"></span><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span><span id="progression-and-related-crafts"></span></p>',5)),n(i,{"asset-id":"spot-blacksmithing"}),a[1]||(a[1]=e('<h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Actividad</th><th>Qué haces</th></tr></thead><tbody><tr><td>Transformar metal</td><td>Funde, refina, alea, forja, trata térmicamente y acaba.</td></tr><tr><td>Cuidar el equipo</td><td>Evalúa materiales, afila filos y realiza pequeñas reparaciones de campo.</td></tr><tr><td>Aprender</td><td>Mantén un diario metalúrgico; explora <a href="/Syrolands-Public/es/guide/characters/techniques.html">técnicas</a> de forja de hojas o armaduras.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Dirección de Syrolands</th></tr></thead><tbody><tr><td>Las herramientas, los lingotes y un menú de fabricación producen armas y armaduras.</td><td>La preparación del material, la forja y el tratamiento térmico definen el resultado.</td></tr><tr><td>La reparación y la calidad excepcional ya forman parte del oficio.</td><td>La calidad del proceso y la evaluación de campo amplían el mantenimiento y la especialización.</td></tr></tbody></table><p>La comparación usa los ciclos conocidos de los oficios de UO; las referencias oficiales también cubren expansiones posteriores. <a href="https://uo.com/wiki/ultima-online-wiki/skills/blacksmithing/" target="_blank" rel="noreferrer">Blacksmithing</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un herrero podría ganarse fama por sus armas de campo duraderas. Elegir un filo más duro puede mejorar una propiedad y aumentar la fragilidad.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progresión y compromisos <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Enlace permanente a &quot;Progresión y compromisos&quot;">​</a></h2><ul><li>El peso, la tenacidad y el rendimiento de corte compiten; ningún material debe ser el mejor para todo.</li><li>Arms Lore explica el rendimiento marcial; Herrería explica los materiales y la estructura. Los límites de reparación y las reglas de materiales siguen abiertos.</li></ul><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/professions/mining.html">Minería</a> · <a href="/Syrolands-Public/es/guide/professions/carpentry.html">Carpintería</a> · <a href="/Syrolands-Public/es/guide/items/item-quality.html">Calidad de objetos</a> · <a href="/Syrolands-Public/es/guide/professions/overview.html">Sistema de profesiones</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/professions/blacksmithing.html">Herrería</a></p>',13))])}const g=r(l,[["render",d]]);export{b as __pageData,g as default};
